using System.Diagnostics;

interface IScannerElement { }

class Open : IScannerElement { }

class Balanced(int run) : IScannerElement
{
  public int Run { get; private set; } = run;
}

public class Solution
{
  public int LongestValidParentheses(string s)
  {
    var best = 0;

    var stack = new Stack<IScannerElement>();
    for (var i = 0; i < s.Length; i++)
    {
      if (s[i] == '(') {
        stack.Push(new Open());
      }
      else
      {
        if (stack.Count == 0)
        {
          continue;
        }

        var element = stack.Pop();
        switch (element)
        {
          case Open:
            stack.Push(new Balanced(2));
            break;
          case Balanced balanced:
            if (stack.Count > 0)
            {
              // must be Open by invariant
              stack.Pop();
              stack.Push(new Balanced(balanced.Run + 2));
            }
            break;
        }

        // Compress stack
        var reducer = 0;
        while (stack.Count > 0 && stack.Peek() is Balanced balanced)
        {
          reducer += balanced.Run;
          stack.Pop();
          if (reducer > best) best = reducer;
        }

        stack.Push(new Balanced(reducer));
      }
    }

    return best;
  }

  public static void Main()
  {
    var solution = new Solution();
    Debug.Assert(solution.LongestValidParentheses("(()") == 2);
    Debug.Assert(solution.LongestValidParentheses(")()())") == 4);
    Debug.Assert(solution.LongestValidParentheses("") == 0);
    Debug.Assert(solution.LongestValidParentheses("()()()()(((") == 8);
    Debug.Assert(solution.LongestValidParentheses(")))))))(((") == 0);
    Debug.Assert(solution.LongestValidParentheses("()()()()(()") == 8);
    Debug.Assert(solution.LongestValidParentheses("))))((()((") == 2);
    Debug.Assert(solution.LongestValidParentheses("()(()") == 2);
    Debug.Assert(solution.LongestValidParentheses("(()(((()") == 2);
    Debug.Assert(solution.LongestValidParentheses(")(((((()())()()))()(()))(") == 22);
